  const s = v === null || v === undefined ? '' : String(v);
  if (/[",\r\n]/.test(s) || /^\s|\s$/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
  return s;
}

function csvLine(fields) {
  return fields.map(csvField).join(',');
}

